import { crypto } from "https://deno.land/std@0.200.0/crypto/mod.ts";

/**
 * Compare two strings in constant time to prevent timing attacks.
 * This implementation uses UTF-8 byte comparison via TextEncoder.
 * 
 * @param a - First string to compare
 * @param b - Second string to compare
 * @returns true if the strings are equal, false otherwise
 */
export function timingSafeEqual(a: string, b: string): boolean {
  const encoder = new TextEncoder();
  const aBytes = encoder.encode(a);
  const bBytes = encoder.encode(b);

  // Early return if lengths differ
  if (aBytes.length !== bBytes.length) {
    return false;
  }

  // Constant-time comparison
  let result = 0;
  for (let i = 0; i < aBytes.length; i++) {
    result |= aBytes[i] ^ bBytes[i];
  }

  return result === 0;
}

/**
 * Generate a random delay (jitter) for security purposes.
 * This helps prevent timing attacks by adding randomness to the response time.
 * 
 * @param min - Minimum delay in milliseconds (default: 0)
 * @param max - Maximum delay in milliseconds (default: 100)
 * @returns Promise that resolves after the random delay
 */
export async function addJitter(min = 0, max = 100): Promise<void> {
  const delay = Math.floor(Math.random() * (max - min + 1)) + min;
  await new Promise((resolve) => setTimeout(resolve, delay));
}

/**
 * Validate a base64 string and decode it.
 * Returns null if the base64 is invalid.
 * 
 * @param b64 - Base64 encoded string
 * @returns Decoded string or null if invalid
 */
export function safeDecodeBase64(b64: string): string | null {
  try {
    // Try to decode the base64 string
    return atob(b64);
  } catch (e) {
    // atob throws an error for invalid base64
    return null;
  }
}

